  int *perm1 = malloc(n * sizeof(int));
  int *count = malloc(n * sizeof(int));
  int *maxflips = malloc(n * sizeof(int));
  int *flips = malloc(n * sizeof(int));
  int *checksum = malloc(n * sizeof(int));
