  flips_count = 0;
  checksum_val = 0;
  max_flips = 0;
  while (1) {
    if (r == n) {
      // compute flips for perm1
      for (i = 0; i < n; i++) perm[i] = perm1[i];
      flips_count = 0;
      while (perm[0] != 0) {
        k = perm[0] + 1;
        for (i = 0, j = k - 1; i < j; i++, j--) {
          int t = perm[i]; perm[i] = perm[j]; perm[j] = t;
        }
        flips_count++;
      }
      if (flips_count > max_flips) max_flips = flips_count;
      if (checksum_val % 2 == 0) checksum_val += flips_count;
      else checksum_val -= flips_count;
    }
    // generate next permutation
    if (r == 1) break;
    // rotate first r elements
    int first = perm1[0];
    for (i = 0; i < r - 1; i++) perm1[i] = perm1[i+1];
    perm1[r-1] = first;
    count[r-1]--;
    if (count[r-1] > 0) continue;
    r++;
    // reset count?
  }
}

