import java.io.*;
import java.nio.charset.StandardCharsets;

public class fasta {
    static final int IM = 139968;
    static final int IA = 3877;
    static final int IC = 29573;
    static int seed = 42;

    static final byte[] ALU = ("GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGGGAGGCCGAGGCGGGCGGA"
            + "TCACCTGAGGTCAGGAGTTCGAGACCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACT"
            + "AAAAATACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCAGCTACTCGGGAG"
            + "GCTGAGGCAGGAGAATCGCTTGAACCCGGGAGGCGGAGGTTGCAGTGAGCCGAGATCGCG"
            + "CCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA").getBytes(StandardCharsets.US_ASCII);

    static final char[] IUB_SYM = "acgtBDHKMNRSVWY".toCharArray();
    static final double[] IUB_PROB = {
        0.27, 0.12, 0.12, 0.27,
        0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02
    };

    static final char[] FREQ_SYM = {'a', 'c', 'g', 't'};
    static final double[] FREQ_PROB = {
        0.3029549426680,
        0.1979883004921,
        0.1975473066391,
        0.3015094502008
    };

    static FastOut out;

    public static void main(String[] args) throws IOException {
        int N = Integer.parseInt(args[0]);
        out = new FastOut(new FileOutputStream(FileDescriptor.out), 1 << 20);

        byte[] header1 = ">ONE Homo sapiens alu\n".getBytes(StandardCharsets.US_ASCII);
        out.write(header1, 0, header1.length);
        writeAlu(2 * N);

        byte[] header2 = ">TWO IUB ambiguity codes\n".getBytes(StandardCharsets.US_ASCII);
        out.write(header2, 0, header2.length);
        byte[] mapIub = buildMap(IUB_SYM, IUB_PROB);
        writeRandom(mapIub, 3 * N);

        byte[] header3 = ">THREE Homo sapiens frequency\n".getBytes(StandardCharsets.US_ASCII);
        out.write(header3, 0, header3.length);
        byte[] mapFreq = buildMap(FREQ_SYM, FREQ_PROB);
        writeRandom(mapFreq, 5 * N);

        out.flush();
    }

    static byte[] buildMap(char[] sym, double[] prob) {
        int n = sym.length;
        double[] cum = new double[n];
        double cp = 0.0;
        for (int i = 0; i < n; i++) {
            cp += prob[i];
            cum[i] = cp;
        }
        byte[] map = new byte[IM];
        for (int s = 0; s < IM; s++) {
            double r = s / (double) IM;
            int i = 0;
            while (r >= cum[i]) {
                i++;
            }
            map[s] = (byte) sym[i];
        }
        return map;
    }

    static void writeAlu(int length) throws IOException {
        int aluLen = ALU.length;
        int idx = 0;
        int remaining = length;
        byte[] line = new byte[61];
        while (remaining > 0) {
            int n = remaining < 60 ? remaining : 60;
            for (int i = 0; i < n; i++) {
                line[i] = ALU[idx++];
                if (idx == aluLen) {
                    idx = 0;
                }
            }
            line[n] = '\n';
            out.write(line, 0, n + 1);
            remaining -= n;
        }
    }

    static void writeRandom(byte[] map, int length) throws IOException {
        byte[] line = new byte[61];
        int lineLen = 0;
        int s = seed;
        for (int i = 0; i < length; i++) {
            s = (s * IA + IC) % IM;
            line[lineLen++] = map[s];
            if (lineLen == 60) {
                line[60] = '\n';
                out.write(line, 0, 61);
                lineLen = 0;
            }
        }
        seed = s;
        if (lineLen > 0) {
            line[lineLen] = '\n';
            out.write(line, 0, lineLen + 1);
        }
    }

    static final class FastOut {
        private final OutputStream out;
        private final byte[] buf;
        private int pos;

        FastOut(OutputStream out, int cap) {
            this.out = out;
            this.buf = new byte[cap];
        }

        void write(byte[] b, int off, int len) throws IOException {
            if (len > buf.length - pos) {
                flush();
                if (len > buf.length) {
                    out.write(b, off, len);
                    return;
                }
            }
            System.arraycopy(b, off, buf, pos, len);
            pos += len;
        }

        void flush() throws IOException {
            if (pos > 0) {
                out.write(buf, 0, pos);
                pos = 0;
            }
        }
    }
}
