public class knucleotide {
    public static void main(String[] args) throws Exception {
        // N from args[0] is unused for this benchmark.
        if (args != null && args.length > 0) {
            try { Integer.parseInt(args[0].trim()); } catch (Exception ignored) {}
        }

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder freeSeq = new StringBuilder();
        LinkedHashMap<String, StringBuilder> records = new LinkedHashMap<>();
        String currentId = null;
        String line;
        while ((line = br.readLine()) != null) {
            if (line.length() > 0 && line.charAt(0) == '>') {
                currentId = line.substring(1).trim();
                if (!records.containsKey(currentId)) {
                    records.put(currentId, new StringBuilder());
                }
            } else {
                String s = line.trim();
                if (s.isEmpty()) continue;
                if (currentId == null) {
                    freeSeq.append(s);
                } else {
                    records.get(currentId).append(s);
                }
            }
        }

        String sequence;
        if (records.isEmpty()) {
            sequence = freeSeq.toString();
        } else {
            String threeId = null;
            for (String id : records.keySet()) {
                if (id.toUpperCase(Locale.US).contains("THREE")) { threeId = id; break; }
            }
            if (threeId != null) {
                sequence = records.get(threeId).toString();
            } else if (records.size() == 1) {
                sequence = records.values().iterator().next().toString();
            } else {
                StringBuilder sb = new StringBuilder();
                for (StringBuilder b : records.values()) sb.append(b);
                sequence = sb.toString();
            }
        }
        sequence = sequence.toUpperCase(Locale.US);

        StringBuilder out = new StringBuilder();
        appendFrequencies(out, sequence, 1);
        appendFrequencies(out, sequence, 2);
        appendCount(out, sequence, "GGT");
        appendCount(out, sequence, "GGTA");
        appendCount(out, sequence, "GGTATT");
        appendCount(out, sequence, "GGTATTTTAATT");
        appendCount(out, sequence, "GGTATTTTAATTTATAGT");
        System.out.print(out);
    }

    private static void appendFrequencies(StringBuilder out, String seq, int k) {
        int n = seq.length();
        HashMap<String, Integer> freq = new HashMap<>();
        for (int i = 0; i + k <= n; i++) {
            String key = seq.substring(i, i + k);
            Integer c = freq.get(key);
            freq.put(key, c == null ? 1 : c + 1);
        }
        List<Map.Entry<String, Integer>> list = new ArrayList<>(freq.entrySet());
        Collections.sort(list, new Comparator<Map.Entry<String, Integer>>() {
            @Override
            public int compare(Map.Entry<String, Integer> a, Map.Entry<String, Integer> b) {
                int c = Integer.compare(b.getValue(), a.getValue());
                if (c != 0) return c;
                return a.getKey().compareTo(b.getKey());
            }
        });
        int total = n - k + 1;
        if (total <= 0) total = 1;
        for (Map.Entry<String, Integer> e : list) {
            out.append(e.getKey()).append(' ');
            out.append(String.format(Locale.US, "%.3f", 100.0 * e.getValue() / total));
            out.append('\n');
        }
        out.append('\n');
    }

    private static void appendCount(StringBuilder out, String seq, String frag) {
        int count = 0;
        int idx = 0;
        int flen = frag.length();
        int n = seq.length();
        while (idx + flen <= n) {
            int found = seq.indexOf(frag, idx);
            if (found < 0) break;
            count++;
            idx = found + 1;
        }
        out.append(count).append('\t').append(frag).append('\n');
    }
}
