import java.math.BigInteger;

public class pidigits {
    public static void main(String[] args) {
        if (args.length == 0) return;
        int N = Integer.parseInt(args[0]);
        if (N <= 0) return;

        // Compute pi to N digits (including the leading 3) using Machin's formula.
        // We use extra guard digits to absorb truncation errors.
        final int GUARD = 100;
        int scale = N - 1 + GUARD;

        BigInteger atan5 = atanInverse(5, scale);
        BigInteger atan239 = atanInverse(239, scale);

        // pi = 16 * atan(1/5) - 4 * atan(1/239)
        BigInteger piScaled = atan5.multiply(BigInteger.valueOf(16))
                             .subtract(atan239.multiply(BigInteger.valueOf(4)));

        BigInteger tenGuard = BigInteger.TEN.pow(GUARD);
        BigInteger digitsVal = piScaled.divide(tenGuard);

        String digits = digitsVal.toString();

        // The result should have exactly N digits. If not, pad with leading zeros.
        if (digits.length() < N) {
            StringBuilder pad = new StringBuilder();
            for (int i = 0; i < N - digits.length(); i++) {
                pad.append('0');
            }
            digits = pad.append(digits).toString();
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < N; i += 10) {
            int end = Math.min(i + 10, N);
            sb.append(digits, i, end);
            sb.append('\t').append(':').append(end).append('\n');
        }
        System.out.print(sb.toString());
    }

    // Returns floor(atan(1/x) * 10^scale) approximately.
    private static BigInteger atanInverse(int x, int scale) {
        BigInteger tenPow = BigInteger.TEN.pow(scale);
        BigInteger xBig = BigInteger.valueOf(x);
        BigInteger x2 = BigInteger.valueOf((long) x * x);

        BigInteger a = tenPow.divide(xBig); // 10^scale / x^(2k+1) for k=0
        BigInteger sum = BigInteger.ZERO;
        int k = 0;
        boolean neg = false;

        while (true) {
            BigInteger term = a.divide(BigInteger.valueOf(2L * k + 1));
            if (term.signum() == 0) break;

            if (neg) {
                sum = sum.subtract(term);
            } else {
                sum = sum.add(term);
            }
            neg = !neg;

            a = a.divide(x2); // move to next odd power of x
            k++;
        }
        return sum;
    }
}
