        if (args.length > 0) {
            int N = Integer.parseInt(args[0]);
        }
        byte[] input = System.in.readAllBytes();
        int len = input.length;
        FastOutput out = new FastOutput(System.out, 1 << 16);
        int pos = 0;
        while (pos < len) {
