                int headerStart = pos;
                int headerEnd = pos;
                while (headerEnd < len && input[headerEnd] != '\n') {
                    headerEnd++;
                }
                int headerLen = headerEnd - headerStart;
                if (headerLen > 0 && input[headerEnd - 1] == '\r') {
                    headerLen--;
                }
                out.write(input, headerStart, headerLen);
                out.writeByte('\n');
                pos = (headerEnd < len) ? headerEnd + 1 : len;
                int seqStart = pos;
                IntList lengths = new IntList();
                int p = pos;
                while (p < len) {
                    if (input[p] == '>') {
                        break;
                    }
                    int lineEnd = p;
                    while (lineEnd < len && input[lineEnd] != '\n') {
                        lineEnd++;
                    }
                    int lineLen = lineEnd - p;
                    if (lineLen > 0 && input[lineEnd - 1] == '\r') {
                        lineLen--;
                    }
                    lengths.add(lineLen);
                    p = (lineEnd < len) ? lineEnd + 1 : len;
