public class revcomp {
    static final byte[] COMP = new byte[256];
    static {
        for (int i = 0; i < 256; i++) COMP[i] = (byte) i;
        COMP['A'] = 'T'; COMP['T'] = 'A';
        COMP['C'] = 'G'; COMP['G'] = 'C';
        COMP['U'] = 'A';
        COMP['R'] = 'Y'; COMP['Y'] = 'R';
        COMP['K'] = 'M'; COMP['M'] = 'K';
        COMP['B'] = 'V'; COMP['V'] = 'B';
        COMP['D'] = 'H'; COMP['H'] = 'D';
        COMP['S'] = 'S'; COMP['W'] = 'W'; COMP['N'] = 'N';
        COMP['a'] = 't'; COMP['t'] = 'a';
        COMP['c'] = 'g'; COMP['g'] = 'c';
        COMP['u'] = 'a';
        COMP['r'] = 'y'; COMP['y'] = 'r';
        COMP['k'] = 'm'; COMP['m'] = 'k';
        COMP['b'] = 'v'; COMP['v'] = 'b';
        COMP['d'] = 'h'; COMP['h'] = 'd';
        COMP['s'] = 's'; COMP['w'] = 'w'; COMP['n'] = 'n';
    }

    static class IntList {
        int[] a = new int[64];
        int size = 0;
        void add(int v) {
            if (size == a.length) {
                int[] b = new int[size * 2];
                System.arraycopy(a, 0, b, 0, size);
                a = b;
            }
            a[size++] = v;
        }
        int size() { return size; }
        int get(int i) { return a[i]; }
    }

    static class FastOutput {
        final OutputStream os;
        final byte[] buf;
        int pos;
        FastOutput(OutputStream os, int size) {
            this.os = os;
            this.buf = new byte[size];
        }
        void writeByte(int b) {
            if (pos == buf.length) flush();
            buf[pos++] = (byte) b;
        }
        void write(byte[] b, int off, int len) {
            while (len > 0) {
                int chunk = Math.min(len, buf.length - pos);
                System.arraycopy(b, off, buf, pos, chunk);
                pos += chunk;
                off += chunk;
                len -= chunk;
                if (pos == buf.length) flush();
            }
        }
        void flush() {
            if (pos > 0) {
                try {
                    os.write(buf, 0, pos);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                pos = 0;
            }
        }
    }

    public static void main(String[] args) throws IOException {
        if (args.length > 0) {
            int N = Integer.parseInt(args[0]);
        }
        byte[] input = System.in.readAllBytes();
        int len = input.length;
        FastOutput out = new FastOutput(System.out, 1 << 16);
        int pos = 0;
        while (pos < len) {
            if (input[pos] == '>') {
                int headerStart = pos;
                int headerEnd = pos;
                while (headerEnd < len && input[headerEnd] != '\n') {
                    headerEnd++;
                }
                int headerLen = headerEnd - headerStart;
                if (headerLen > 0 && input[headerEnd - 1] == '\r') {
                    headerLen--;
                }
                out.write(input, headerStart, headerLen);
                out.writeByte('\n');
                pos = (headerEnd < len) ? headerEnd + 1 : len;
                int seqStart = pos;
                IntList lengths = new IntList();
                int p = pos;
                while (p < len) {
                    if (input[p] == '>') {
                        break;
                    }
                    int lineEnd = p;
                    while (lineEnd < len && input[lineEnd] != '\n') {
                        lineEnd++;
                    }
                    int lineLen = lineEnd - p;
                    if (lineLen > 0 && input[lineEnd - 1] == '\r') {
                        lineLen--;
                    }
                    lengths.add(lineLen);
                    p = (lineEnd < len) ? lineEnd + 1 : len;
                }
                int seqEnd = p;
                int seqPtr = seqEnd - 1;
                int nLines = lengths.size();
                for (int i = 0; i < nLines; i++) {
                    int L = lengths.get(i);
                    for (int j = 0; j < L; j++) {
                        while (seqPtr >= seqStart && (input[seqPtr] == '\n' || input[seqPtr] == '\r')) {
                            seqPtr--;
                        }
                        if (seqPtr < seqStart) {
                            break;
                        }
                        byte b = input[seqPtr--];
                        out.writeByte(COMP[b & 0xFF]);
                    }
                    out.writeByte('\n');
                }
                pos = p;
            } else {
                pos++;
            }
        }
        out.flush();
    }
}
